<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('assessor');$user=current_user();$flashes=render_flashes();$currentPage='activity_log';$pageTitle='Activity Log';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$rows=[];$exists=as_has_table($conn,'assessor_activity_log');if($uid<=0){http_response_code(403);exit('Invalid Assessor account.');}if($exists){$s=$conn->prepare('SELECT * FROM assessor_activity_log WHERE assessor_id=? ORDER BY created_at DESC,id DESC LIMIT 200');$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}require __DIR__.'/_layout_start.php';?>
<div class="as-page-header"><div><span class="as-page-header__eyebrow">Audit & Accountability</span><h2>Activity Log</h2><p>Review recorded actions performed through your Assessor account.</p></div></div><?php if(!$exists):?><div class="as-alert as-alert--warning"><i class="fas fa-database"></i><div><strong>Activity log table is not installed.</strong><span>Import database/assessor_portal.sql from this package.</span></div></div><?php endif;?><div class="as-card"><div class="as-card__header"><div><h3>Audit Trail</h3><p>Latest recorded Assessor actions.</p></div></div><?php if(!$rows):?><div class="as-empty"><div class="as-empty__icon"><i class="fas fa-clock-rotate-left"></i></div><strong>No activity recorded</strong><span>Assessment actions will appear here once recorded.</span></div><?php else:?><div class="as-activity-list"><?php foreach($rows as $x):?><article class="as-activity"><div class="as-activity__icon"><i class="fas fa-fingerprint"></i></div><div class="as-activity__body"><div class="as-activity__title"><strong><?= e(as_label($x['action'])) ?></strong><span><?= e(as_datetime($x['created_at'])) ?></span></div><p><?= e($x['description']) ?></p><div class="as-activity__meta"><?php if($x['entity_type']):?><span><i class="fas fa-tag"></i> <?= e(as_label($x['entity_type'])) ?><?= $x['entity_id']?' #'.(int)$x['entity_id']:'' ?></span><?php endif;?><?php if($x['ip_address']):?><span><i class="fas fa-globe"></i> <?= e($x['ip_address']) ?></span><?php endif;?></div></div></article><?php endforeach;?></div><?php endif;?></div><?php require __DIR__.'/_layout_end.php';?>
